<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$root=dirname(__DIR__);
spl_autoload_register(static function(string $class) use($root):void{$prefix='App\\';if(!str_starts_with($class,$prefix))return;$file=$root.'/app/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($file))require_once $file;});
$tenant=0;$apply=false;foreach($argv as $arg){if(str_starts_with($arg,'--tenant='))$tenant=(int)substr($arg,9);if($arg==='--apply')$apply=true;}
if($tenant<=0){fwrite(STDERR,"Uso: php tools/consolidar-modulos-assinatura.php --tenant=ID [--apply]\nSem --apply apenas mostra a simulação.\n");exit(2);}
try{$service=new \App\Services\SubscriptionModuleService();$result=$service->consolidateLegacy($tenant,0,$apply);$sub=$result['subscription']??null;if(!$sub)throw new RuntimeException('Assinatura não encontrada para a empresa.');echo "Empresa/tenant: {$tenant}\n";echo "Assinatura principal: #".(int)$sub['id']." · ciclo ".($sub['billing_cycle']??'monthly')."\n";echo "Total principal atual: R$ ".number_format((float)($result['total']??0),2,',','.')."\n";echo "Adicionais legados separados: R$ ".number_format((float)($result['legacy_monthly']??0),2,',','.')."/mês\n";foreach(($result['legacy_items']??[]) as $item)echo " - #".(int)$item['id'].' '.($item['module_name']??'Módulo').' · R$ '.number_format((float)$item['monthly_price'],2,',','.')."/mês\n";if(!$apply){echo "\nSIMULAÇÃO APENAS. Para consolidar: php tools/consolidar-modulos-assinatura.php --tenant={$tenant} --apply\n";}else{foreach(($result['applied']??[]) as $item)echo "[OK] Consolidado: {$item['module']} · novo total R$ ".number_format((float)$item['new_total'],2,',','.')."\n";echo "CONSOLIDAÇÃO CONCLUÍDA.\n";}}catch(Throwable $e){fwrite(STDERR,"[ERRO] ".$e->getMessage()."\n");exit(1);}
